/* ---------- change control & code migrations ---------- */
const CR_FLOW=['Draft','Assessed','Approved','Implemented','Verified','Closed'];
const CR_TYPES=['Code Migration','Database Migration','Bug Fix / Patch','Configuration','Infrastructure'];
const IMPACTS=[['di','Data integrity impact (ALCOA+)'],['validated','Affects validated state — regression required'],['p11','Affects Part 11 controls (audit trail, e-sign, access)'],['sop','Requires SOP / document updates'],['training','Requires user training'],['data','Requires data migration / conversion']];
const LANG_EXT={javascript:'js',python:'py',sql:'sql',text:'txt'};
const curCR=()=>S.changes.find(x=>x.id===parseHash().id);
function vChanges(){const q=UI.crQ.toLowerCase();const list=S.changes.filter(c=>(UI.crF==='All'||(UI.crF==='Open'?openCR(c):!openCR(c)))&&(!q||(c.id+' '+c.title+' '+c.type).toLowerCase().includes(q)));
  return {title:'Change Control',fab:'crNew',html:`<div class="ph"><div class="t"><h1>Change control &amp; migrations</h1><p>Code, database and infrastructure changes — impact/risk assessment, QA approval, rule-based migration workbench, regression evidence.</p></div><button class="btn pri hide-m" data-act="crNew">+ New change</button></div>
  <div class="toolbar"><input class="search" data-inp="crQ" placeholder="Search changes…" value="${esc(UI.crQ)}">${seg('crF',['Open','Closed','All'])}</div>
  <div class="card p0 list">${list.map(c=>`<a class="item" href="#/change/${c.id}"><span class="id">${c.id}</span><div class="main1"><div class="ttl">${esc(c.title)}</div><div class="meta"><span>${esc(c.type)}</span><span>${esc(c.lang)}</span><span>Risk ${esc(c.risk)}</span><span>${esc(userName(c.owner))}</span></div></div>${pill(c.status)}</a>`).join('')||'<div class="empty">No changes.</div>'}</div>`}}
ACT.crNew=()=>{const m=modal('New change request',`<label class="f">Title<input class="inp" id="ncT" placeholder="e.g. Migrate reporting module to Python 3.11"></label>
  <div class="fields"><label class="f">Change type<select class="inp" id="ncY">${opts(CR_TYPES)}</select></label><label class="f">Language / artefact<select class="inp" id="ncL">${opts([['javascript','JavaScript (executable tests)'],['python','Python'],['sql','SQL'],['text','Other / none']])}</select></label><label class="f">Risk<select class="inp" id="ncR">${opts(['High','Medium','Low'],'Medium')}</select></label></div>
  <label class="f">Source baseline (JavaScript only)<select class="inp" id="ncB"><option value="">— paste source later —</option>${S.code.filter(c=>c.status==='Baseline').map(c=>`<option value="${c.id}">${c.id} ${esc(c.label)}</option>`).join('')}</select></label>
  <label class="f">Description<textarea class="inp" id="ncD"></textarea></label><label class="f">Justification<input class="inp" id="ncJ"></label>`,`<button class="btn" data-x>Cancel</button><button class="btn pri" id="ncGo">Raise change</button>`);
  $('#ncGo',m).onclick=()=>{const title=val('ncT',m).trim();if(!title){toast('Title required');return}const lang=val('ncL',m);const b=lang==='javascript'?S.code.find(c=>c.id===val('ncB',m)):null;
    const pack={javascript:'es5-es2015',python:'py2-py3',sql:'oracle-pg'}[lang]||'custom';const id=nextId('CR');
    S.changes.unshift({id,title,type:val('ncY',m),lang,status:'Draft',requester:S.currentUser,owner:S.currentUser,created:nowISO(),description:val('ncD',m),justification:val('ncJ',m),risk:val('ncR',m),gamp:'5',fromCV:b?b.id:null,toLabel:'',pack,rules:clone(RULE_PACKS[pack].rules),sourceCode:b?b.code:'',targetCode:'',
      impact:{},impactNotes:'',plan:[{step:'Back up current baseline',done:false},{step:'Implement change',done:false},{step:'Execute regression tests',done:false}],tests:lang==='javascript'?S.tests.filter(t=>t.mode==='auto').map(t=>t.id):[],history:[{at:nowISO(),by:S.currentUser,text:'Raised'}],signatures:[]});
    audit('Change request raised',id,title);save();closeModal();location.hash='#/change/'+id}};
function crLastRun(c){const h=sha256(c.targetCode||'');return S.runs.filter(r=>r.cr===c.id&&r.codeHash===h).sort(byAt).at(-1)}
function vChange(p){const c=S.changes.find(x=>x.id===p.id);if(!c)return {title:'Not found',html:'<div class="empty">Change not found.</div>'};
  const locked=!openCR(c);const early=['Draft','Assessed'].includes(c.status);
  let acts='';
  if(c.status==='Draft')acts=`<button class="btn pri" data-act="crAssess">✍ Complete assessment</button>`;
  if(c.status==='Assessed')acts=`<button class="btn pri" data-act="crApprove">✍ QA approve</button><button class="btn bad" data-act="crReject">Reject</button>`;
  if(c.status==='Approved')acts=`<button class="btn pri" data-act="crImplement">Mark implemented</button>`;
  if(c.status==='Implemented')acts=`<button class="btn pri" data-act="crVerify">✍ Verify</button>`;
  if(c.status==='Verified')acts=`<button class="btn pri" data-act="crClose">✍ QA close &amp; promote</button>`;
  const [tab,tb]=tabsBar('cr',[['ov','Overview'],['imp','Impact & risk'],['work','Migration workbench'],['plan',`Plan (${c.plan.filter(x=>x.done).length}/${c.plan.length})`],['ver','Tests & defects'],['sig','Signatures & history']],'ov');
  let body='';
  if(tab==='ov')body=`<div class="grid g2"><div class="card"><h2>Summary</h2><dl class="kv"><dt>Type</dt><dd>${esc(c.type)}</dd><dt>Artefact</dt><dd>${esc(c.lang)}</dd><dt>Risk</dt><dd>${pill(c.risk)}</dd><dt>GAMP category</dt><dd>${esc(c.gamp)}</dd><dt>Requester</dt><dd>${esc(userName(c.requester))}</dd><dt>Owner</dt><dd>${esc(userName(c.owner))}</dd><dt>From baseline</dt><dd>${c.fromCV?link(c.fromCV):'—'}</dd><dt>Target</dt><dd>${esc(c.toLabel||'—')}</dd><dt>Raised</dt><dd>${fmtD(c.created)}</dd></dl></div>
    <div class="card"><h2>Release gates</h2>${readiness(c).map(([k,l])=>`<div class="chk" style="align-items:center">${k?'<span class="res pass">✓</span>':'<span class="res fail">✕</span>'}<span>${esc(l)}</span></div>`).join('')}</div></div>
    <div class="card"><h2>Description</h2>${early&&!locked?`<textarea class="inp" id="crD">${esc(c.description)}</textarea><label class="f" style="margin-top:10px">Justification<input class="inp" id="crJ" value="${esc(c.justification)}"></label><div class="fields" style="margin-top:10px"><label class="f">Title<input class="inp" id="crT" value="${esc(c.title)}"></label><label class="f">Target version label<input class="inp" id="crL" value="${esc(c.toLabel)}"></label><label class="f">Owner<select class="inp" id="crO">${userOpts(c.owner)}</select></label></div><div class="row" style="justify-content:flex-end;margin-top:10px"><button class="btn pri" data-act="crSaveOv">Save</button></div>`:`<p>${esc(c.description)}</p><p class="muted small"><b>Justification:</b> ${esc(c.justification)}</p>`}</div>`;
  if(tab==='imp')body=`<div class="card"><h2>Impact assessment</h2>${IMPACTS.map(([k,l])=>`<label class="chk"><input type="checkbox" id="im_${k}" ${c.impact[k]?'checked':''} ${early?'':'disabled'}> ${esc(l)}</label>`).join('')}
    <div class="fields" style="margin-top:12px"><label class="f">Overall risk<select class="inp" id="imR" ${early?'':'disabled'}>${opts(['High','Medium','Low'],c.risk)}</select></label><label class="f">GAMP 5 category<select class="inp" id="imG" ${early?'':'disabled'}>${opts([['1','1 — Infrastructure'],['3','3 — Non-configured'],['4','4 — Configured'],['5','5 — Custom']],c.gamp)}</select></label></div>
    <label class="f" style="margin-top:12px">Assessment rationale<textarea class="inp" id="imN" ${early?'':'disabled'}>${esc(c.impactNotes)}</textarea></label>
    ${early?`<div class="row" style="justify-content:flex-end;margin-top:10px"><button class="btn pri" data-act="crSaveImp">Save assessment</button></div>`:'<div class="small muted" style="margin-top:8px">Assessment locked after QA approval.</div>'}</div>`;
  if(tab==='work')body=workbench(c,locked,early);
  if(tab==='plan')body=`<div class="card"><h2>Implementation &amp; rollback plan</h2>${c.plan.map((s,i)=>`<div class="chk" style="align-items:center"><input type="checkbox" data-chg="crStep" data-i="${i}" ${s.done?'checked':''} ${['Approved','Implemented'].includes(c.status)?'':'disabled'}><span style="flex:1;${s.done?'text-decoration:line-through;color:var(--muted)':''}">${esc(s.step)}</span>${early?`<button class="btn sm ghost" data-act="crStepDel" data-i="${i}">✕</button>`:''}</div>`).join('')}
    ${early?`<div class="row" style="margin-top:10px"><input class="inp" id="psN" placeholder="Add a step…" style="flex:1"><button class="btn" data-act="crStepAdd">Add</button></div>`:''}<div class="small muted" style="margin-top:8px">${early?'Steps can be checked off once QA has approved the change.':''}</div></div>`;
  if(tab==='ver'){const last=crLastRun(c);const bugs=S.defects.filter(d=>d.cr===c.id);
    body=`<div class="card"><div class="row"><h2 style="flex:1;margin:0">Regression suite</h2>${c.lang==='javascript'&&!locked?`<button class="btn pri" data-act="crRun" ${c.targetCode?'':'disabled'}>▶ Run on candidate</button>`:''}</div>
      <div class="small muted" style="margin:4px 0 10px">${c.lang==='javascript'?`Executes linked automated tests against the candidate (sha256 ${short(sha256(c.targetCode||''))}).`:'Non-executable artefact — attach manual verification evidence via test cases.'}</div>
      ${S.tests.map(t=>{const lr=last&&last.results.find(x=>x.tc===t.id);return `<label class="chk" style="align-items:center"><input type="checkbox" data-chg="crTest" data-id="${t.id}" ${c.tests.includes(t.id)?'checked':''} ${locked?'disabled':''}>${resIcon(lr&&lr.status)}<span style="flex:1"><a href="#/test/${t.id}" class="mono">${t.id}</a> ${esc(t.title)} <span class="muted small">${t.mode}</span></span></label>`}).join('')}
      ${last?`<div class="small" style="margin-top:8px">Latest run on current candidate: ${link(last.id)} · ${fmtDT(last.at)}</div>`:''}</div>
      <div class="card"><div class="row"><h2 style="flex:1;margin:0">Linked defects</h2><button class="btn" data-act="bugNew" data-cr="${c.id}">+ Raise defect</button></div><div class="list" style="margin-top:8px">${bugs.map(b=>`<a class="item" href="#/defect/${b.id}" style="padding:10px 0"><span class="id">${b.id}</span><div class="main1"><div class="ttl">${esc(b.title)}</div></div>${pill(b.severity)} ${pill(b.status)}</a>`).join('')||'<div class="muted small">None.</div>'}</div></div>`}
  if(tab==='sig')body=`<div class="grid g2"><div class="card"><h2>Signatures</h2>${sigsHTML(c)}</div><div class="card"><h2>History</h2>${histHTML(c.history)}</div></div>`;
  return {title:c.id,back:'#/changes',html:`<div class="ph"><div class="t"><div class="row"><span class="mono muted">${c.id}</span>${pill(c.status)}<span class="pill brand">${esc(c.type)}</span>${pill('Risk '+c.risk,statusTone(c.risk))}</div><h1 style="margin-top:6px">${esc(c.title)}</h1>${stepper(CR_FLOW,c.status==='Rejected'?'Draft':c.status)}</div></div>
    <div class="row" style="margin-bottom:12px">${acts}<span style="flex:1"></span><button class="btn" data-act="crDoc">▤ Generate change record</button></div>${tb}${body}`}}
function workbench(c,locked,early){
  const pk=RULE_PACKS[c.pack]||RULE_PACKS.custom;const res=applyRules(c.sourceCode,c.rules);const preview=early||!c.targetCode;
  const tgt=preview?res.out:c.targetCode;const df=diffHTML(c.sourceCode,tgt);const canSrc=!locked&&!['Implemented','Verified'].includes(c.status);const canTgt=['Approved','Implemented','Verified'].includes(c.status);
  return `${early?`<div class="card" style="border-color:var(--warn);background:var(--warnSoft)"><b>Preview mode.</b> <span class="small">Per SOP-QA-007 implementation is locked until QA approval — rules run as a dry-run preview and nothing is written to the target.</span></div>`:''}
  <div class="grid g2"><div class="card"><div class="row"><h2 style="flex:1;margin:0">Rule pack</h2><select class="inp" style="width:auto" data-chg="crPack" ${canSrc?'':'disabled'}>${Object.entries(RULE_PACKS).map(([k,v])=>`<option value="${k}" ${k===c.pack?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>
    <div class="small muted" style="margin:6px 0 8px">${c.rules.length} rules · ${res.counts.reduce((a,b)=>a+b,0)} matches in source${res.errors.length?` · <span class="err">${esc(res.errors.join('; '))}</span>`:''}</div>
    ${c.rules.map((r,i)=>`<div class="chk" style="align-items:center"><input type="checkbox" data-chg="crRule" data-i="${i}" ${r.off?'':'checked'} ${canSrc?'':'disabled'}><div style="flex:1;min-width:0"><div class="small b">${esc(r.desc||'Rule '+(i+1))}</div><div class="mono muted" style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">/${esc(r.find)}/${esc(r.flags||'')} → ${esc(r.replace)}</div></div><span class="pill ${res.counts[i]?'brand':''}">${res.counts[i]}</span>${canSrc?`<button class="btn sm ghost" data-act="crRuleDel" data-i="${i}">✕</button>`:''}</div>`).join('')||'<div class="muted small">No rules — add custom find/replace rules below.</div>'}
    ${canSrc?`<details style="margin-top:10px"><summary class="small b" style="cursor:pointer">+ Add custom rule (regex)</summary><div class="fields" style="margin-top:8px"><label class="f">Find (regex)<input class="inp mono" id="rfF"></label><label class="f">Replace<input class="inp mono" id="rfR"></label><label class="f">Flags<input class="inp mono" id="rfG" value="g"></label><label class="f">Description<input class="inp" id="rfD"></label></div><div class="row" style="justify-content:flex-end;margin-top:8px"><button class="btn" data-act="crRuleAdd">Add rule</button></div></details>`:''}
    ${!early&&canTgt&&!locked?`<div class="row" style="margin-top:12px"><button class="btn pri" data-act="crApply" style="flex:1">⇄ Apply rules → write target</button></div>`:''}</div>
  <div class="card"><h2>Source ${c.fromCV?`<span class="muted small">(${c.fromCV})</span>`:''}</h2><textarea class="inp code" id="wbS" ${canSrc?'':'readonly'}>${esc(c.sourceCode)}</textarea>
    ${canSrc?`<div class="row" style="justify-content:flex-end;margin-top:8px"><button class="btn" data-act="crSaveSrc">Save source</button></div>`:''}</div></div>
  <div class="card"><div class="row"><h2 style="flex:1;margin:0">${preview?'Preview diff':'Target'} · <span style="color:var(--ok)">+${df.add}</span> <span style="color:var(--bad)">−${df.del}</span></h2>${c.targetCode?blobLink(c.targetCode,`${c.id}_${c.toLabel||'target'}.${LANG_EXT[c.lang]||'txt'}`,'text/plain','⬇ Target','btn sm'):''}</div>
    <div class="hashv" style="margin:4px 0 10px">${c.targetCode?'target sha256 '+sha256(c.targetCode):'no target written yet'}</div>
    <div class="tabs" style="margin-bottom:10px"><button class="${UI.wbView!=='edit'?'on':''}" data-act="set" data-k="wbView" data-v="diff">Diff</button>${canTgt&&!locked&&c.targetCode?`<button class="${UI.wbView==='edit'?'on':''}" data-act="set" data-k="wbView" data-v="edit">Edit target (manual changes)</button>`:''}</div>
    ${UI.wbView==='edit'&&canTgt&&!locked&&c.targetCode?`<textarea class="inp code" id="wbT" style="min-height:380px">${esc(c.targetCode)}</textarea><div class="row" style="justify-content:flex-end;margin-top:8px"><button class="btn pri" data-act="crSaveTgt">Save target</button></div>`:df.html}
    ${c.lang==='javascript'&&c.targetCode&&!locked?`<div class="row" style="margin-top:12px"><button class="btn pri" data-act="crRun">▶ Run regression on target</button><span class="small muted">${(()=>{const l=crLastRun(c);return l?`Last run ${l.id}: ${l.results.filter(x=>x.status==='Pass').length}/${l.results.length} pass`:'Not yet run on this version'})()}</span></div>`:''}</div>`}
function syncWB(c){const s=$('#wbS');if(s&&!s.readOnly&&s.value!==c.sourceCode){c.sourceCode=s.value;audit('Source modified',c.id,'sha256 '+short(sha256(c.sourceCode)))}}
ACT.crSaveOv=()=>{const c=curCR();Object.assign(c,{description:val('crD'),justification:val('crJ'),title:val('crT').trim()||c.title,toLabel:val('crL').trim(),owner:val('crO')});hist(c,'Details edited');audit('Change modified',c.id,'Overview');save();render();toast('Saved')};
ACT.crSaveImp=()=>{const c=curCR();IMPACTS.forEach(([k])=>c.impact[k]=val('im_'+k));c.risk=val('imR');c.gamp=val('imG');c.impactNotes=val('imN');hist(c,'Assessment updated');audit('Impact assessment updated',c.id,`Risk ${c.risk}, GAMP ${c.gamp}`);save();render();toast('Assessment saved')};
ACT.crAssess=()=>{const c=curCR();if(!guard(c.impactNotes&&c.impactNotes.trim(),'Complete the Impact & risk tab (rationale required) first.')){UI.tabs.cr='imp';render();return}
  esign({record:c,meanings:['Assessed'],title:'Sign impact & risk assessment',onSign:()=>{c.status='Assessed';hist(c,'Assessed');audit('Status → Assessed',c.id,'Risk '+c.risk)}})};
ACT.crApprove=()=>{const c=curCR();if(!guard(isQA(),'Only QA can approve changes. Switch to Morgan Lee (QA Approver).'))return;if(!guard(c.requester!==S.currentUser,'Requester cannot approve own change.'))return;
  esign({record:c,meanings:['Approved'],title:'QA approval — change control',onSign:()=>{c.status='Approved';hist(c,'Approved');audit('Status → Approved',c.id,'')}})};
ACT.crReject=b=>{const c=curCR();if(!guard(isQA(),'Only QA can reject.'))return;armed(b,()=>{c.status='Rejected';hist(c,'Rejected');audit('Status → Rejected',c.id,'');save();render()})};
ACT.crImplement=()=>{const c=curCR();if(!guard(c.lang==='text'||c.targetCode,'Write the target in the Migration workbench first (Apply rules).'))return;c.status='Implemented';hist(c,'Implemented');audit('Status → Implemented',c.id,c.targetCode?'target sha256 '+short(sha256(c.targetCode)):'');save();render()};
ACT.crVerify=()=>{const c=curCR();if(!guard(hasRole('Tester')||isQA(),'Verification requires a QA Tester or QA Approver.'))return;
  if(c.lang==='javascript'&&c.tests.length){const l=crLastRun(c);if(!guard(l,'Run the regression suite on the current candidate first.'))return;if(!guard(l.results.every(x=>x.status==='Pass'),`Regression ${l.id} has failures — fix and re-run before verification.`))return}
  const ob=S.defects.filter(d=>d.cr===c.id&&openBug(d));if(!guard(!ob.length,`Open linked defects: ${ob.map(d=>d.id).join(', ')}`))return;
  esign({record:c,meanings:['Verified'],title:'Verification signature',onSign:()=>{c.status='Verified';hist(c,'Verified');audit('Status → Verified',c.id,'')}})};
ACT.crClose=()=>{const c=curCR();if(!guard(isQA(),'Only QA can close changes.'))return;if(!guard(c.plan.every(p=>p.done),'All plan steps must be complete.'))return;
  esign({record:c,meanings:['Closed'],title:'QA closure — promote to production baseline',onSign:()=>{c.status='Closed';hist(c,'Closed');audit('Status → Closed',c.id,'');
    if(c.lang==='javascript'&&c.targetCode){S.code.filter(x=>x.status==='Baseline'&&(x.id===c.fromCV||!c.fromCV)).forEach(x=>{x.status='Retired';audit('Baseline retired',x.id,'Superseded via '+c.id)});const cv={id:nextId('CV'),label:c.toLabel||c.id,title:`LabTrack core module ${c.toLabel||''}`.trim(),lang:'javascript',status:'Baseline',code:c.targetCode,created:nowISO(),by:S.currentUser,cr:c.id};cv.hash=sha256(cv.code);S.code.push(cv);audit('Code baseline registered',cv.id,`${cv.label} sha256 ${short(cv.hash)} via ${c.id}`);setTimeout(()=>toast(`Promoted ${cv.id} as new baseline`),50)}}})};
CHG.crStep=e=>{const c=curCR();const s=c.plan[+e.dataset.i];s.done=e.checked;audit(s.done?'Plan step completed':'Plan step reopened',c.id,s.step);save();render()};
ACT.crStepAdd=()=>{const c=curCR();const v=val('psN').trim();if(!v)return;c.plan.push({step:v,done:false});audit('Plan step added',c.id,v);save();render()};
ACT.crStepDel=b=>{const c=curCR();const [s]=c.plan.splice(+b.dataset.i,1);audit('Plan step removed',c.id,s.step);save();render()};
CHG.crTest=e=>{const c=curCR();const id=e.dataset.id;c.tests=e.checked?[...new Set([...c.tests,id])]:c.tests.filter(x=>x!==id);audit(e.checked?'Test linked':'Test unlinked',c.id,id);save();render()};
CHG.crPack=e=>{const c=curCR();syncWB(c);c.pack=e.value;c.rules=clone(RULE_PACKS[e.value].rules);audit('Rule pack selected',c.id,RULE_PACKS[e.value].name);save();render()};
CHG.crRule=e=>{const c=curCR();syncWB(c);c.rules[+e.dataset.i].off=!e.checked;save();render()};
ACT.crRuleDel=b=>{const c=curCR();syncWB(c);const [r]=c.rules.splice(+b.dataset.i,1);audit('Migration rule removed',c.id,r.desc||r.find);save();render()};
ACT.crRuleAdd=()=>{const c=curCR();syncWB(c);const r={find:val('rfF'),replace:val('rfR'),flags:val('rfG')||'g',desc:val('rfD')||'Custom rule'};if(!r.find){toast('Find pattern required');return}try{new RegExp(r.find,r.flags)}catch(e){toast('Invalid regex: '+e.message);return}c.rules.push(r);audit('Migration rule added',c.id,r.desc);save();render()};
ACT.crSaveSrc=()=>{const c=curCR();const v=val('wbS');if(v===c.sourceCode){toast('No changes');return}c.sourceCode=v;audit('Source modified',c.id,'sha256 '+short(sha256(v)));save();render();toast('Source saved')};
ACT.crApply=()=>{const c=curCR();syncWB(c);const r=applyRules(c.sourceCode,c.rules);if(r.errors.length){toast(r.errors[0]);return}c.targetCode=r.out;if(!c.toLabel)c.toLabel='candidate';hist(c,`Rules applied (${r.counts.reduce((a,b)=>a+b,0)} replacements)`);audit('Migration rules applied',c.id,`${RULE_PACKS[c.pack]?.name||c.pack} → sha256 ${short(sha256(c.targetCode))}`);if(c.status==='Verified'){c.status='Implemented';hist(c,'Returned to Implemented (target changed)')}save();UI.wbView='diff';render();toast('Target written')};
ACT.crSaveTgt=()=>{const c=curCR();const v=val('wbT');if(v===c.targetCode){toast('No changes');return}const d=diffLines(c.targetCode,v);c.targetCode=v;hist(c,`Target edited (+${d.add} −${d.del})`);audit('Target code modified',c.id,`+${d.add} −${d.del} lines → sha256 ${short(sha256(v))}`);if(c.status==='Verified'){c.status='Implemented';hist(c,'Returned to Implemented (target changed)')}save();UI.wbView='diff';render();toast('Target saved — re-run regression')};
ACT.crRun=async b=>{const c=curCR();const tcs=S.tests.filter(t=>c.tests.includes(t.id)&&t.mode==='auto');if(!guard(tcs.length,'Link at least one automated test.'))return;b.disabled=true;b.textContent='Running…';
  const r=await executeRun(tcs,c.targetCode,c.id,`${c.toLabel||'candidate'} (${c.id})`,c.id);const p=r.results.filter(x=>x.status==='Pass').length;toast(`${r.id}: ${p}/${r.results.length} passed`);render()};
ACT.crDoc=()=>{const c=curCR();const id=nextId('DOC');const last=crLastRun(c);
  const content=`# Change Control Record — ${c.id}\n\n| Field | Value |\n|---|---|\n| Title | ${c.title} |\n| Type | ${c.type} |\n| Status | ${c.status} |\n| Risk | ${c.risk} |\n| GAMP category | ${c.gamp} |\n| Requester | ${userName(c.requester)} |\n| From baseline | ${c.fromCV||'—'} |\n| Target | ${c.toLabel||'—'} |\n| Target sha256 | ${c.targetCode?sha256(c.targetCode):'—'} |\n\n## Description\n${c.description}\n\n## Justification\n${c.justification}\n\n## Impact assessment\n`+IMPACTS.map(([k,l])=>`- ${c.impact[k]?'**Yes**':'No'} — ${l}`).join('\n')+`\n\n${c.impactNotes}\n\n## Migration rules applied\n| # | Rule | Pattern |\n|---|---|---|\n`+(c.rules.filter(r=>!r.off).map((r,i)=>`| ${i+1} | ${r.desc} | \`${r.find.replace(/\|/g,'\\u007c')}\` |`).join('\n')||'| — | none | |')+`\n\n## Plan\n`+c.plan.map(s=>`- ${s.done?'[x]':'[ ]'} ${s.step}`).join('\n')+`\n\n## Verification evidence\n`+(last?`Regression ${last.id} (${fmtUTC(last.at)}): ${last.results.filter(x=>x.status==='Pass').length}/${last.results.length} passed. Evidence sha256 ${last.hash}.`:'No regression run on current candidate.')+`\n\n## Linked defects\n`+(S.defects.filter(d=>d.cr===c.id).map(d=>`- ${d.id} ${d.title} — ${d.status}`).join('\n')||'- None')+`\n\n## Signatures\n`+(c.signatures||[]).map(s=>`- ${s.meaning}: ${s.name} (${s.role}) ${fmtUTC(s.at)} — ${s.reason}`).join('\n');
  S.docs.unshift({id,type:'CCR',title:`Change Control Record ${c.id}`,version:'0.1',status:'Draft',owner:S.currentUser,content,created:nowISO(),updated:nowISO(),history:[{at:nowISO(),by:S.currentUser,text:'Generated from '+c.id}],signatures:[]});audit('Document generated',id,'Change record for '+c.id);save();UI.tabs.doc='view';location.hash='#/doc/'+id};

/* ---------- test execution ---------- */
async function executeRun(tcs,code,target,label,cr){const {results,engine}=await runSuite(code,tcs);
  results.forEach(r=>{const t=S.tests.find(x=>x.id===r.tc);r.testVersion=t.version;r.testStatus=t.status});
  const run={id:nextId('TR'),at:nowISO(),by:S.currentUser,target,codeLabel:label,codeHash:sha256(code),cr:cr||null,engine,results,signatures:[]};run.hash=sha256(JSON.stringify(run.results));S.runs.push(run);
  audit('Test run executed',run.id,`${results.filter(x=>x.status==='Pass').length}/${results.length} passed on ${label}`);save();return run}
function vTests(){const [tab,tb]=tabsBar('tests',[['cases',`Test cases (${S.tests.length})`],['runs',`Test runs (${S.runs.length})`]],'cases');
  const targets=codeTargets().filter(t=>t.lang==='javascript');if(!UI.tcTarget||!targets.find(t=>t.id===UI.tcTarget))UI.tcTarget=(targets.find(t=>/Baseline/.test(t.label))||targets[0]||{}).id||'';
  let body='';
  if(tab==='cases'){const q=UI.tcQ.toLowerCase();const list=S.tests.filter(t=>(UI.tcT==='All'||t.type===UI.tcT)&&(!q||(t.id+' '+t.title).toLowerCase().includes(q)));const sel=[...UI.tcSel].filter(id=>S.tests.find(t=>t.id===id&&t.mode==='auto'));
    body=`<div class="card" style="margin-bottom:12px"><div class="row"><b style="flex:1;min-width:140px">Execute automated suite</b><select class="inp" style="width:auto;max-width:100%" data-chg="tcTarget">${targets.map(t=>`<option value="${t.id}" ${t.id===UI.tcTarget?'selected':''}>${esc(t.label)}</option>`).join('')}</select><button class="btn" data-act="tcSelAll">Select all automated</button><button class="btn pri" data-act="tcRunSel" ${sel.length&&UI.tcTarget?'':'disabled'}>▶ Run ${sel.length||''} &amp; record</button></div><div class="small muted" style="margin-top:6px">Tests run in a sandboxed Web Worker against the selected code version. Results are hash-sealed as GxP evidence.</div></div>
    <div class="toolbar"><input class="search" data-inp="tcQ" placeholder="Search tests…" value="${esc(UI.tcQ)}">${seg('tcT',['All','IQ','OQ','PQ'])}</div>
    <div class="card p0 list">${list.map(t=>{const l=latestResult(t.id);return `<div class="item" style="cursor:default">${t.mode==='auto'?`<input type="checkbox" data-chg="tcSel" data-id="${t.id}" ${UI.tcSel.has(t.id)?'checked':''} style="width:18px;height:18px;accent-color:var(--brand)">`:'<span style="width:18px"></span>'}${resIcon(l&&l.status)}<a href="#/test/${t.id}" class="main1" style="color:inherit"><div class="ttl">${esc(t.title)}</div><div class="meta"><span class="mono">${t.id}</span><span>${t.type}</span><span>${t.mode==='auto'?'Automated':'Manual'}</span><span>v${t.version}</span><span>${t.reqs.join(', ')||'no requirements'}</span></div></a>${pill(t.status)}</div>`}).join('')||'<div class="empty">No tests.</div>'}</div>`}
  else body=`<div class="card p0 list">${S.runs.slice().reverse().map(r=>{const p=r.results.filter(x=>x.status==='Pass').length;return `<a class="item" href="#/run/${r.id}"><span class="id">${r.id}</span><div class="main1"><div class="ttl">${esc(r.codeLabel)}</div><div class="meta"><span>${fmtDT(r.at)}</span><span>${esc(userName(r.by))}</span><span>${r.results.length} test case${r.results.length>1?'s':''}</span>${sigsAt(r,'Reviewed').length?'<span style="color:var(--ok)">✓ reviewed</span>':''}</div></div>${pill(`${p}/${r.results.length} pass`,p===r.results.length?'ok':'bad')}</a>`}).join('')||'<div class="empty">No runs yet.</div>'}</div>`;
  return {title:'Test Automation',fab:'tcNew',html:`<div class="ph"><div class="t"><h1>Test automation</h1><p>Scripted IQ/OQ/PQ test cases — automated (JavaScript assertions) or manual step-by-step — traced to requirements.</p></div><button class="btn pri hide-m" data-act="tcNew">+ New test case</button></div>${tb}${body}`}}
CHG.tcTarget=e=>{UI.tcTarget=e.value;render()};
CHG.tcSel=e=>{e.checked?UI.tcSel.add(e.dataset.id):UI.tcSel.delete(e.dataset.id);render()};
ACT.tcSelAll=()=>{const auto=S.tests.filter(t=>t.mode==='auto');const all=auto.every(t=>UI.tcSel.has(t.id));auto.forEach(t=>all?UI.tcSel.delete(t.id):UI.tcSel.add(t.id));render()};
ACT.tcRunSel=async b=>{const tg=codeTargets().find(t=>t.id===UI.tcTarget);const tcs=S.tests.filter(t=>UI.tcSel.has(t.id)&&t.mode==='auto');if(!tg||!tcs.length)return;b.disabled=true;b.textContent='Running…';
  const isCR=tg.id.startsWith('CR');const lbl=isCR?`${S.changes.find(c=>c.id===tg.id).toLabel||'candidate'} (${tg.id})`:`${S.code.find(c=>c.id===tg.id).label} ${S.code.find(c=>c.id===tg.id).status.toLowerCase()}`;
  const r=await executeRun(tcs,tg.code,tg.id,lbl,isCR?tg.id:null);location.hash='#/run/'+r.id};
ACT.tcNew=()=>{const m=modal('New test case',`<label class="f">Title<input class="inp" id="ntT" placeholder="e.g. Dose ceiling for pediatric patients"></label><div class="fields"><label class="f">Type<select class="inp" id="ntY">${opts(['OQ','PQ','IQ','Unit','Regression'])}</select></label><label class="f">Mode<select class="inp" id="ntM">${opts([['auto','Automated (script)'],['manual','Manual (steps)']])}</select></label></div>`,`<button class="btn" data-x>Cancel</button><button class="btn pri" id="ntGo">Create</button>`);
  $('#ntGo',m).onclick=()=>{const title=val('ntT',m).trim();if(!title){toast('Title required');return}const id=nextId('TC');const mode=val('ntM',m);
    S.tests.push({id,title,type:val('ntY',m),reqs:[],mode,script:mode==='auto'?`test('describe the expected behaviour', () => {\n  // sut = exports of the system under test\n  expect(sut.withinSpec(100, 95, 105)).toBe(true);\n});`:'',steps:mode==='manual'?[{action:'',expected:''}]:[],status:'Draft',version:'0.1',author:S.currentUser,created:nowISO()});
    audit('Test case created',id,title);save();closeModal();location.hash='#/test/'+id}};
const curTC=()=>S.tests.find(x=>x.id===parseHash().id);
const API_HELP=`test(name, fn) · expect(x).toBe(y) · .toEqual(obj) · .toBeCloseTo(n, dp) · .toBeTruthy() · .toBeFalsy() · .toBeGreaterThan(n) · .toBeLessThan(n) · .toContain(v) · .toMatch(re) · .toHaveLength(n) · .toThrow(msg) · .not.toBe(y) · console.log() · sut.* = system-under-test exports`;
function vTest(p){const t=S.tests.find(x=>x.id===p.id);if(!t)return {title:'Not found',html:'<div class="empty">Test not found.</div>'};
  const runs=S.runs.filter(r=>r.results.some(x=>x.tc===t.id)).slice().reverse();const baseline=S.code.find(c=>c.status==='Baseline');
  return {title:t.id,back:'#/tests',html:`<div class="ph"><div class="t"><div class="row"><span class="mono muted">${t.id}</span>${pill(t.status)}<span class="pill brand">${t.type}</span><span class="pill">${t.mode==='auto'?'Automated':'Manual'}</span><span class="pill">v${t.version}</span></div><h1 style="margin-top:6px">${esc(t.title)}</h1><p>Author ${esc(userName(t.author))}${t.status==='Approved'?' · editing an approved test returns it to Draft':''}</p></div></div>
  <div class="row" style="margin-bottom:12px">${t.status==='Draft'?'<button class="btn" data-act="tcApprove">✍ QA approve test</button>':''}${t.mode==='auto'?`<button class="btn" data-act="tcDry">▷ Dry run vs ${esc(baseline?baseline.label:'baseline')} (not recorded)</button>`:`<button class="btn pri" data-act="tcManual">▶ Execute &amp; record</button>`}</div>
  <div id="dry"></div>
  <div class="grid g2" style="grid-template-columns:minmax(0,1.5fr) minmax(0,1fr)"><div class="card">
    <div class="fields"><label class="f">Title<input class="inp" id="tT" value="${esc(t.title)}"></label><label class="f">Type<select class="inp" id="tY">${opts(['IQ','OQ','PQ','Unit','Regression'],t.type)}</select></label></div>
    ${t.mode==='auto'?`<label class="f" style="margin-top:12px">Automated script<textarea class="inp code" id="tS" style="min-height:340px">${esc(t.script)}</textarea></label><div class="small muted" style="margin-top:6px;font-family:var(--mono);font-size:11px">${esc(API_HELP)}</div>`:
      `<div class="small b" style="margin-top:14px">Steps</div>${t.steps.map((s,i)=>`<div class="fields" style="margin-top:8px;grid-template-columns:24px 1fr 1fr 34px;align-items:start"><b class="muted" style="padding-top:9px">${i+1}</b><textarea class="inp" style="min-height:60px" data-step="a${i}" placeholder="Action">${esc(s.action)}</textarea><textarea class="inp" style="min-height:60px" data-step="e${i}" placeholder="Expected result">${esc(s.expected)}</textarea><button class="btn sm ghost" data-act="tcStepDel" data-i="${i}">✕</button></div>`).join('')}<button class="btn sm" style="margin-top:8px" data-act="tcStepAdd">+ Step</button>`}
    <div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn pri" data-act="tcSave">Save test case</button></div></div>
  <div><div class="card"><h2>Requirements covered</h2>${S.reqs.map(r=>`<label class="chk"><input type="checkbox" class="tcReq" value="${r.id}" ${t.reqs.includes(r.id)?'checked':''}><span><span class="mono">${r.id}</span> ${esc(r.text)}</span></label>`).join('')}</div>
  <div class="card"><h2>Execution history</h2>${runs.map(r=>{const x=r.results.find(z=>z.tc===t.id);return `<a class="item" href="#/run/${r.id}" style="padding:8px 0">${resIcon(x.status)}<div class="main1"><div class="ttl small">${r.id} · ${esc(r.codeLabel)}</div><div class="meta">${fmtDT(r.at)} · v${x.testVersion||'?'}</div></div></a>`}).join('')||'<div class="muted small">Never executed.</div>'}</div>
  <div class="card"><h2>Signatures</h2>${sigsHTML(t)}</div></div></div>`}}
function readSteps(t){t.steps.forEach((s,i)=>{const a=$(`[data-step="a${i}"]`),e=$(`[data-step="e${i}"]`);if(a)s.action=a.value;if(e)s.expected=e.value})}
ACT.tcStepAdd=()=>{const t=curTC();readSteps(t);t.steps.push({action:'',expected:''});render()};
ACT.tcStepDel=b=>{const t=curTC();readSteps(t);t.steps.splice(+b.dataset.i,1);render()};
ACT.tcSave=()=>{const t=curTC();const before=JSON.stringify([t.title,t.type,t.script,t.steps,t.reqs]);t.title=val('tT').trim()||t.title;t.type=val('tY');if(t.mode==='auto')t.script=val('tS');else readSteps(t);t.reqs=$$('.tcReq').filter(x=>x.checked).map(x=>x.value);
  if(JSON.stringify([t.title,t.type,t.script,t.steps,t.reqs])===before){toast('No changes');return}
  const [M,m]=t.version.split('.').map(Number);t.version=`${M}.${(m||0)+1}`;if(t.status==='Approved'){t.status='Draft';toast('Saved v'+t.version+' — returned to Draft, re-approval required')}else toast('Saved v'+t.version);audit('Test case modified',t.id,'v'+t.version);save();render()};
ACT.tcApprove=()=>{const t=curTC();if(!guard(isQA(),'Only QA can approve test cases. Switch to Morgan Lee.'))return;if(!guard(t.author!==S.currentUser,'Author cannot approve own test.'))return;
  esign({record:t,meanings:['Approved for execution'],title:'Approve test case',onSign:()=>{const [M,m]=t.version.split('.').map(Number);if(m||!M)t.version=`${M+1}.0`;t.status='Approved';audit('Test case approved',t.id,'v'+t.version)}})};
ACT.tcDry=async b=>{const t=curTC();const s=val('tS');const base=S.code.find(c=>c.status==='Baseline');if(!base){toast('No baseline code');return}b.disabled=true;const {results,engine}=await runSuite(base.code,[{id:t.id,script:s}]);b.disabled=false;$('#dry').innerHTML=consoleHTML(results,`Dry run · ${base.label} · ${engine} · NOT RECORDED`)};
function consoleHTML(results,head){return `<div class="console" style="margin-bottom:14px"><span class="h">${esc(head)}</span>\n`+results.map(r=>`\n<span class="h">${esc(r.tc)}</span> ${r.status==='Pass'?'<span class="p">PASS</span>':`<span class="f">${r.status.toUpperCase()}</span>`} <span class="d">${r.ms} ms</span>\n`+r.cases.map(c=>`  ${c.status==='Pass'?'<span class="p">✓</span>':'<span class="f">✕</span>'} ${esc(c.name)}${c.msg?`\n      <span class="f">${esc(c.msg)}</span>`:''}`).join('\n')+(r.logs&&r.logs.length?'\n'+r.logs.map(l=>`  <span class="d">› ${esc(l)}</span>`).join('\n'):'')).join('\n')+'</div>'}
ACT.tcManual=()=>{const t=curTC();const m=modal(`Execute ${t.id} — ${t.title}`,`<div class="small muted">Record contemporaneous actual results for each step (ALCOA+). Executed as ${esc(me().name)}.</div>`+t.steps.map((s,i)=>`<div class="card flat" style="padding:12px"><div class="small b">Step ${i+1}: ${esc(s.action)}</div><div class="small muted">Expected: ${esc(s.expected)}</div><textarea class="inp" style="min-height:54px;margin-top:8px" id="mx${i}" placeholder="Actual result"></textarea><div class="seg" style="margin-top:8px"><label style="padding:4px 10px"><input type="radio" name="mr${i}" value="Pass" checked> Pass</label><label style="padding:4px 10px"><input type="radio" name="mr${i}" value="Fail"> Fail</label></div></div>`).join(''),`<button class="btn" data-x>Cancel</button><button class="btn pri" id="mxGo">Record execution</button>`,true);
  $('#mxGo',m).onclick=()=>{const cases=t.steps.map((s,i)=>({name:s.action,status:m.querySelector(`input[name=mr${i}]:checked`).value,msg:`Expected: ${s.expected} | Actual: ${val('mx'+i,m)}`,actual:val('mx'+i,m)}));if(cases.some(c=>!c.actual.trim())){toast('Enter an actual result for every step');return}
    const st=cases.some(c=>c.status==='Fail')?'Fail':'Pass';const run={id:nextId('TR'),at:nowISO(),by:S.currentUser,target:'MANUAL',codeLabel:`Manual execution — ${S.system.name} validation env`,codeHash:null,cr:null,engine:'manual',results:[{tc:t.id,status:st,ms:0,cases,logs:[],testVersion:t.version,testStatus:t.status}],signatures:[]};run.hash=sha256(JSON.stringify(run.results));S.runs.push(run);
    audit('Manual test executed',run.id,`${t.id} ${st}`);save();closeModal();location.hash='#/run/'+run.id}};
function vRun(p){const r=S.runs.find(x=>x.id===p.id);if(!r)return {title:'Not found',html:'<div class="empty">Run not found.</div>'};
  const pass=r.results.filter(x=>x.status==='Pass').length;const intact=sha256(JSON.stringify(r.results))===r.hash;const evidence=JSON.stringify({run:r,exported:nowISO(),app:'GxP Studio '+APP_VERSION},null,2);
  return {title:r.id,back:'#/tests',html:`<div class="ph"><div class="t"><div class="row"><span class="mono muted">${r.id}</span>${pill(`${pass}/${r.results.length} pass`,pass===r.results.length?'ok':'bad')}${sigsAt(r,'Reviewed').length?pill('Reviewed','ok'):pill('Awaiting review','warn')}</div><h1 style="margin-top:6px">${esc(r.codeLabel)}</h1><p>Executed ${fmtUTC(r.at)} by ${esc(userName(r.by))} · ${esc(r.engine)}</p></div></div>
  <div class="row" style="margin-bottom:12px"><button class="btn pri" data-act="runSign">✍ Review &amp; sign</button><button class="btn" data-act="runTSR">▤ Generate test summary report</button>${blobLink(evidence,`${r.id}_evidence.json`,'application/json','⬇ Evidence')}</div>
  <div class="grid g2"><div class="card"><dl class="kv"><dt>Target</dt><dd>${r.target==='MANUAL'?'Manual':link(r.target)}</dd><dt>Code sha256</dt><dd class="hashv">${r.codeHash||'n/a (manual)'}</dd><dt>Change</dt><dd>${r.cr?link(r.cr):'—'}</dd><dt>Evidence sha256</dt><dd class="hashv">${r.hash}</dd><dt>Integrity</dt><dd>${intact?pill('Evidence unaltered','ok'):pill('TAMPERED','bad')}</dd></dl></div><div class="card"><h2>Review</h2>${sigsHTML(r)}</div></div>
  <div class="card p0" style="margin-top:14px">${r.results.map(x=>{const t=S.tests.find(z=>z.id===x.tc)||{title:'(deleted)'};const bug=S.defects.find(d=>d.run===r.id&&d.tc===x.tc);return `<div style="padding:14px 16px;border-bottom:1px solid var(--line)"><div class="row">${resIcon(x.status)}<a href="#/test/${x.tc}" class="mono">${x.tc}</a><b style="flex:1">${esc(t.title)}</b><span class="small muted">${x.ms} ms · v${x.testVersion||'?'}${x.testStatus==='Draft'?' (draft script)':''}</span>${x.status!=='Pass'?(bug?link(bug.id):`<button class="btn sm bad" data-act="runBug" data-tc="${x.tc}">+ Raise defect</button>`):''}</div>
    <div style="margin:6px 0 0 30px">${x.cases.map(c=>`<div class="small" style="padding:2px 0">${c.status==='Pass'?'<span style="color:var(--ok)">✓</span>':'<span style="color:var(--bad)">✕</span>'} ${esc(c.name)}${c.msg?`<div class="mono" style="color:${c.status==='Pass'?'var(--muted)':'var(--bad)'};font-size:11.5px;margin-left:16px">${esc(c.msg)}</div>`:''}</div>`).join('')}</div></div>`}).join('')}</div>
  <h2 style="margin:18px 0 10px">Console</h2>${consoleHTML(r.results,`${r.id} · ${r.codeLabel} · ${r.engine}`)}`}}
const curRun=()=>S.runs.find(x=>x.id===parseHash().id);
ACT.runSign=()=>{const r=curRun();if(!guard(r.by!==S.currentUser,'Independent review: the executor cannot review their own run. Switch user.'))return;esign({record:Object.assign(r,{title:r.codeLabel}),meanings:['Reviewed'],title:'Review test evidence'})};
ACT.runBug=b=>{const r=curRun();const x=r.results.find(z=>z.tc===b.dataset.tc);const t=S.tests.find(z=>z.id===x.tc);const f=x.cases.filter(c=>c.status!=='Pass');
  bugModal({title:`${t.title}: ${f[0]?f[0].name:'failure'} (${r.codeLabel})`,severity:'Major',gxp:'High',tc:x.tc,run:r.id,cr:r.cr||'',found:'Test execution',description:`Failure in ${r.id} (${t.id} v${x.testVersion}).\n`+f.map(c=>`- ${c.name}: ${c.msg}`).join('\n'),actual:f.map(c=>c.msg).join('; ')})};
ACT.runTSR=()=>{const r=curRun();const id=nextId('DOC');const pass=r.results.filter(x=>x.status==='Pass').length;
  const content=`# Test Summary Report — ${r.id}\n\n| Field | Value |\n|---|---|\n| System | ${S.system.name} |\n| Target | ${r.codeLabel} |\n| Code sha256 | ${r.codeHash||'n/a'} |\n| Executed by | ${userName(r.by)} |\n| Executed at | ${fmtUTC(r.at)} |\n| Engine | ${r.engine} |\n| Evidence sha256 | ${r.hash} |\n\n## Results\n${pass} of ${r.results.length} test cases passed.\n\n| Test case | Title | Requirements | Result | Cases |\n|---|---|---|---|---|\n`+r.results.map(x=>{const t=S.tests.find(z=>z.id===x.tc)||{title:'',reqs:[]};return `| ${x.tc} | ${t.title} | ${t.reqs.join(', ')||'—'} | **${x.status}** | ${x.cases.filter(c=>c.status==='Pass').length}/${x.cases.length} |`}).join('\n')+`\n\n## Deviations\n`+(r.results.filter(x=>x.status!=='Pass').map(x=>{const b=S.defects.find(d=>d.run===r.id&&d.tc===x.tc);return `- ${x.tc}: ${x.cases.filter(c=>c.status!=='Pass').map(c=>c.msg).join('; ')} → ${b?b.id:'defect not yet raised'}`}).join('\n')||'- None')+`\n\n## Conclusion\n${pass===r.results.length?'All test cases met their acceptance criteria.':'Acceptance criteria NOT met. Release is blocked pending defect resolution and re-execution.'}`;
  S.docs.unshift({id,type:'TSR',title:`Test Summary Report ${r.id}`,version:'0.1',status:'Draft',owner:S.currentUser,content,created:nowISO(),updated:nowISO(),history:[{at:nowISO(),by:S.currentUser,text:'Generated from '+r.id}],signatures:[]});audit('Document generated',id,'TSR for '+r.id);save();UI.tabs.doc='view';location.hash='#/doc/'+id};

/* ---------- defects & CAPA ---------- */
const BUG_FLOW=['Open','Investigating','Fix In Progress','Ready for Verification','Verified','Closed'];
const RC_CATS=['Requirements','Design','Code','Configuration','Data','Test script','Procedure / human error','Vendor / third party','Infrastructure'];
function vDefects(){const q=UI.bugQ.toLowerCase();const list=S.defects.filter(d=>(UI.bugF==='All'||(UI.bugF==='Open'?openBug(d):!openBug(d)))&&(!q||(d.id+' '+d.title).toLowerCase().includes(q)));
  return {title:'Defects & CAPA',fab:'bugNew',html:`<div class="ph"><div class="t"><h1>Defects, deviations &amp; CAPA</h1><p>Bug fixes with root-cause analysis, corrective/preventive actions and verification evidence.</p></div><button class="btn pri hide-m" data-act="bugNew">+ Raise defect</button></div>
  <div class="toolbar"><input class="search" data-inp="bugQ" placeholder="Search defects…" value="${esc(UI.bugQ)}">${seg('bugF',['Open','Closed','All'])}</div>
  <div class="card p0 list">${list.map(d=>`<a class="item" href="#/defect/${d.id}"><span class="id">${d.id}</span><div class="main1"><div class="ttl">${esc(d.title)}</div><div class="meta"><span>GxP ${d.gxp}</span><span>${esc(userName(d.assignee))}</span>${d.cr?`<span class="mono">${d.cr}</span>`:''}${d.tc?`<span class="mono">${d.tc}</span>`:''}<span>${ago(d.created)}</span></div></div>${pill(d.severity)}${pill(d.status)}</a>`).join('')||'<div class="empty">No defects.</div>'}</div>`}}
function bugModal(pre){pre=pre||{};const m=modal('Raise defect / deviation',`<label class="f">Title<input class="inp" id="nbT" value="${esc(pre.title||'')}"></label>
  <div class="fields"><label class="f">Severity<select class="inp" id="nbS">${opts(['Critical','Major','Minor'],pre.severity||'Major')}</select></label><label class="f">GxP impact<select class="inp" id="nbG">${opts(['High','Medium','Low'],pre.gxp||'Medium')}</select></label><label class="f">Assignee<select class="inp" id="nbA">${userOpts('u1')}</select></label></div>
  <div class="fields"><label class="f">Test case<select class="inp" id="nbC"><option value="">—</option>${S.tests.map(t=>`<option value="${t.id}" ${t.id===pre.tc?'selected':''}>${t.id} ${esc(t.title)}</option>`).join('')}</select></label><label class="f">Change control<select class="inp" id="nbR"><option value="">—</option>${S.changes.map(c=>`<option value="${c.id}" ${c.id===pre.cr?'selected':''}>${c.id} ${esc(c.title)}</option>`).join('')}</select></label></div>
  <label class="f">Description<textarea class="inp" id="nbD">${esc(pre.description||'')}</textarea></label><div class="fields"><label class="f">Expected<input class="inp" id="nbE" value="${esc(pre.expected||'')}"></label><label class="f">Actual<input class="inp" id="nbX" value="${esc(pre.actual||'')}"></label></div>`,`<button class="btn" data-x>Cancel</button><button class="btn pri" id="nbGo">Raise</button>`);
  $('#nbGo',m).onclick=()=>{const title=val('nbT',m).trim();if(!title){toast('Title required');return}const id=nextId('BUG');
    S.defects.unshift({id,title,severity:val('nbS',m),gxp:val('nbG',m),status:'Open',reporter:S.currentUser,assignee:val('nbA',m),created:nowISO(),found:pre.found||'Manual report',run:pre.run||null,tc:val('nbC',m)||null,cr:val('nbR',m)||null,description:val('nbD',m),steps:'',expected:val('nbE',m),actual:val('nbX',m),rcCategory:'',rootCause:'',fix:'',capa:{corrective:'',preventive:'',effectiveness:''},history:[{at:nowISO(),by:S.currentUser,text:'Raised'+(pre.run?' from '+pre.run:'')}],signatures:[]});
    if(pre.dev){const v=S.deviations.find(x=>x.id===pre.dev);if(v){v.bugs.push(id);hist(v,'Linked '+id);audit('CAPA linked',v.id,id)}}
    audit('Defect raised',id,title);save();closeModal();location.hash='#/defect/'+id}}
ACT.bugNew=b=>bugModal(b&&b.dataset&&b.dataset.cr?{cr:b.dataset.cr}:{});
const curBug=()=>S.defects.find(x=>x.id===parseHash().id);
function vDefect(p){const d=S.defects.find(x=>x.id===p.id);if(!d)return {title:'Not found',html:'<div class="empty">Defect not found.</div>'};
  const lock=d.status==='Closed';const i=BUG_FLOW.indexOf(d.status);const next=BUG_FLOW[i+1];const ro=lock?'disabled':'';
  const tr=d.tc?latestResult(d.tc,r=>r.at>=d.created):null;
  return {title:d.id,back:'#/defects',html:`<div class="ph"><div class="t"><div class="row"><span class="mono muted">${d.id}</span>${pill(d.status)}${pill(d.severity)}${pill('GxP '+d.gxp,statusTone(d.gxp))}</div><h1 style="margin-top:6px">${esc(d.title)}</h1><p>Reported by ${esc(userName(d.reporter))} · ${fmtD(d.created)} · ${esc(d.found)}</p>${stepper(BUG_FLOW,d.status)}</div></div>
  <div class="row" style="margin-bottom:12px">${next?`<button class="btn pri" data-act="bugAdv">${['Verified','Closed'].includes(next)?'✍ ':''}Move to ${esc(next)}</button>`:''}${!lock?'<button class="btn" data-act="bugSave">Save changes</button>':''}</div>
  <div class="grid g2"><div class="card"><h2>Details</h2>
    <label class="f">Title<input class="inp" id="bT" value="${esc(d.title)}" ${ro}></label>
    <div class="fields" style="margin-top:10px"><label class="f">Severity<select class="inp" id="bS" ${ro}>${opts(['Critical','Major','Minor'],d.severity)}</select></label><label class="f">GxP impact<select class="inp" id="bG" ${ro}>${opts(['High','Medium','Low'],d.gxp)}</select></label><label class="f">Assignee<select class="inp" id="bA" ${ro}>${userOpts(d.assignee)}</select></label></div>
    <label class="f" style="margin-top:10px">Description<textarea class="inp" id="bD" ${ro}>${esc(d.description)}</textarea></label>
    <div class="fields" style="margin-top:10px"><label class="f">Expected<input class="inp" id="bE" value="${esc(d.expected)}" ${ro}></label><label class="f">Actual<input class="inp" id="bX" value="${esc(d.actual)}" ${ro}></label></div>
    <div class="fields" style="margin-top:10px"><label class="f">Test case<select class="inp" id="bC" ${ro}><option value="">—</option>${S.tests.map(t=>`<option value="${t.id}" ${t.id===d.tc?'selected':''}>${t.id} ${esc(t.title)}</option>`).join('')}</select></label><label class="f">Change control<select class="inp" id="bR" ${ro}><option value="">—</option>${S.changes.map(c=>`<option value="${c.id}" ${c.id===d.cr?'selected':''}>${c.id}</option>`).join('')}</select></label></div>
    <div class="small" style="margin-top:10px">${d.run?`Found in ${link(d.run)}`:''} ${d.tc?` · Latest ${link(d.tc)} result since raised: ${tr?`${resIcon(tr.status)} ${link(tr.run.id)}`:'<span class="muted">not re-run yet</span>'}`:''}</div></div>
  <div><div class="card"><h2>Root cause analysis</h2><label class="f">Root cause category<select class="inp" id="bK" ${ro}><option value="">— select —</option>${opts(RC_CATS,d.rcCategory)}</select></label>
    <label class="f" style="margin-top:10px">Root cause (5 whys)<textarea class="inp" id="bRC" ${ro} placeholder="Why 1… Why 2… Why 3…">${esc(d.rootCause)}</textarea></label>
    <label class="f" style="margin-top:10px">Fix description (bug fix)<textarea class="inp" id="bF" ${ro} placeholder="What was changed and where (link the change control)">${esc(d.fix)}</textarea></label>
    ${d.cr&&!lock?`<div class="small" style="margin-top:8px">Apply the code fix in ${link(d.cr)} → Migration workbench → Edit target, then re-run regression.</div>`:''}</div>
  <div class="card"><h2>CAPA</h2><label class="f">Corrective action<textarea class="inp" id="bCA" ${ro}>${esc(d.capa.corrective)}</textarea></label><label class="f" style="margin-top:10px">Preventive action<textarea class="inp" id="bPA" ${ro}>${esc(d.capa.preventive)}</textarea></label><label class="f" style="margin-top:10px">Effectiveness check<textarea class="inp" id="bEC" ${ro}>${esc(d.capa.effectiveness)}</textarea></label></div></div></div>
  <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Signatures</h2>${sigsHTML(d)}</div><div class="card"><h2>History</h2>${histHTML(d.history)}</div></div>`}}
function readBug(d){if(!$('#bT'))return false;const b=JSON.stringify(d);Object.assign(d,{title:val('bT').trim()||d.title,severity:val('bS'),gxp:val('bG'),assignee:val('bA'),description:val('bD'),expected:val('bE'),actual:val('bX'),tc:val('bC')||null,cr:val('bR')||null,rcCategory:val('bK'),rootCause:val('bRC'),fix:val('bF')});Object.assign(d.capa,{corrective:val('bCA'),preventive:val('bPA'),effectiveness:val('bEC')});return JSON.stringify(d)!==b}
ACT.bugSave=()=>{const d=curBug();if(readBug(d)){hist(d,'Edited');audit('Defect modified',d.id,'');save();render();toast('Saved')}else toast('No changes')};
ACT.bugAdv=()=>{const d=curBug();if(d.status!=='Closed'&&readBug(d)){hist(d,'Edited');audit('Defect modified',d.id,'')}const next=BUG_FLOW[BUG_FLOW.indexOf(d.status)+1];
  const go=()=>{d.status=next;hist(d,next);audit('Status → '+next,d.id,'');save();render()};
  if(next==='Fix In Progress'&&!guard(d.rcCategory&&d.rootCause.trim(),'Document the root cause category and analysis first.')){save();render();return}
  if(next==='Ready for Verification'&&!guard(d.fix.trim(),'Describe the fix first.')){save();render();return}
  if(next==='Verified'){if(!guard(hasRole('Tester')||isQA(),'Verification requires a QA Tester or QA Approver. Switch user.'))return;
    const t=d.tc&&S.tests.find(x=>x.id===d.tc);if(t&&t.mode==='auto'){const l=latestResult(t.id,r=>r.at>=d.created);if(!guard(l&&l.status==='Pass',`${t.id} must pass in a recorded run after the defect was raised.`))return}
    esign({record:d,meanings:['Verified — fix effective'],title:'Verify defect fix',onSign:()=>{d.status='Verified';hist(d,'Verified');audit('Status → Verified',d.id,'')}});return}
  if(next==='Closed'){if(!guard(isQA(),'Only QA can close defects.'))return;if(d.gxp!=='Low'&&!guard(d.capa.corrective.trim()&&d.capa.preventive.trim(),'GxP-impacting defects require corrective and preventive actions.'))return;
    esign({record:d,meanings:['Closed'],title:'QA closure',onSign:()=>{d.status='Closed';hist(d,'Closed');audit('Status → Closed',d.id,'')}});return}
  go()};
